  <script>
    const arabicMonths = [
      "يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
      "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"
    ];

    const today = new Date();
    let viewYear = today.getFullYear();
    let viewMonth = today.getMonth();
    let selectedDate = null;
    let selectedTime = null;

    const daysElement = document.getElementById("days");
    const monthNameElement = document.getElementById("monthName");
    const timeSlotsElement = document.getElementById("timeSlots");
    const summaryElement = document.getElementById("selectionSummary");
    const confirmButton = document.getElementById("confirmBooking");
    const toastElement = document.getElementById("toast");

    function sameDate(a, b) {
      return a && b &&
        a.getFullYear() === b.getFullYear() &&
        a.getMonth() === b.getMonth() &&
        a.getDate() === b.getDate();
    }

    function formatSelectedDate(date) {
      return `${date.getDate()} ${arabicMonths[date.getMonth()]} ${date.getFullYear()}`;
    }

    function renderCalendar() {
      monthNameElement.textContent = `${arabicMonths[viewMonth]} ${viewYear}`;
      daysElement.innerHTML = "";

      const firstDay = new Date(viewYear, viewMonth, 1);
      const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
      const previousMonthDays = new Date(viewYear, viewMonth, 0).getDate();
      const saturdayOffset = (firstDay.getDay() + 1) % 7;

      for (let index = 0; index < 42; index++) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "day";

        let date;
        let muted = false;

        if (index < saturdayOffset) {
          const day = previousMonthDays - saturdayOffset + index + 1;
          date = new Date(viewYear, viewMonth - 1, day);
          muted = true;
        } else if (index < saturdayOffset + daysInMonth) {
          date = new Date(viewYear, viewMonth, index - saturdayOffset + 1);
        } else {
          const day = index - saturdayOffset - daysInMonth + 1;
          date = new Date(viewYear, viewMonth + 1, day);
          muted = true;
        }

        button.textContent = date.getDate();
        button.dataset.date = `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
        button.setAttribute("aria-label", formatSelectedDate(date));

        if (muted) {
          button.disabled = true;
        } else {
          button.addEventListener("click", () => selectDate(date));
        }

        if (sameDate(date, today)) {
          button.classList.add("today");
          button.setAttribute("aria-current", "date");
        }

        if (sameDate(date, selectedDate)) {
          button.classList.add("selected");
          button.setAttribute("aria-selected", "true");
        }

        daysElement.appendChild(button);
      }
    }

    function selectDate(date) {
      selectedDate = date;
      selectedTime = null;
      renderCalendar();
      renderTimeSlots();
      updateSummary();
    }

    function renderTimeSlots() {
      const times = [
        "9:00 ص", "9:30 ص", "10:00 ص",
        "10:30 ص", "11:00 ص", "11:30 ص",
        "12:00 م"
      ];

      timeSlotsElement.innerHTML = "";

      times.forEach((time, index) => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "time-slot";
        button.textContent = time;

        const isUnavailable = selectedDate && (selectedDate.getDate() + index) % 5 === 0;
        if (isUnavailable) {
          button.classList.add("unavailable");
          button.disabled = true;
          button.setAttribute("aria-label", `${time} غير متاح`);
        } else {
          button.addEventListener("click", () => {
            selectedTime = time;
            renderTimeSlots();
            updateSummary();
          });
        }

        if (selectedTime === time) {
          button.classList.add("selected");
          button.setAttribute("aria-pressed", "true");
        }

        timeSlotsElement.appendChild(button);
      });
    }

    function updateSummary() {
      if (selectedDate && selectedTime) {
        summaryElement.textContent = `${formatSelectedDate(selectedDate)}، ${selectedTime}`;
        confirmButton.disabled = false;
      } else if (selectedDate) {
        summaryElement.textContent = "اختر الوقت المناسب لإكمال الحجز";
        confirmButton.disabled = true;
      } else {
        summaryElement.textContent = "اختر التاريخ والوقت لتأكيد الحجز";
        confirmButton.disabled = true;
      }
    }

    function showToast(message, isError = false) {
      toastElement.textContent = message;
      toastElement.classList.toggle("error", isError);
      toastElement.classList.add("show");
      clearTimeout(showToast.timer);
      showToast.timer = setTimeout(() => {
        toastElement.classList.remove("show");
      }, 3200);
    }

    document.getElementById("nextMonth").addEventListener("click", () => {
      viewMonth++;
      if (viewMonth > 11) {
        viewMonth = 0;
        viewYear++;
      }
      selectedDate = null;
      selectedTime = null;
      renderCalendar();
      renderTimeSlots();
      updateSummary();
    });

    document.getElementById("previousMonth").addEventListener("click", () => {
      viewMonth--;
      if (viewMonth < 0) {
        viewMonth = 11;
        viewYear--;
      }
      selectedDate = null;
      selectedTime = null;
      renderCalendar();
      renderTimeSlots();
      updateSummary();
    });

    confirmButton.addEventListener("click", () => {
      if (!selectedDate || !selectedTime) {
        showToast("يرجى اختيار التاريخ والوقت أولًا.", true);
        return;
      }

      showToast(`تم تأكيد موعدك يوم ${formatSelectedDate(selectedDate)} الساعة ${selectedTime}.`);
      confirmButton.disabled = true;
    });

    document.querySelector(".back-button").addEventListener("click", () => {
      showToast("تم الرجوع إلى صفحة مواعيدك.");
    });

    document.querySelector(".help-button").addEventListener("click", () => {
      showToast("يمكنك الاتصال بخدمة العملاء على 800 8442.");
    });

    renderCalendar();
    renderTimeSlots();
    updateSummary();
  </script>
